1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	import java.util.OptionalInt;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	
13	/**
14	 * Shared household rules for the owner-create pipeline. A household is now keyed on
15	 * {@code (lastName, postcode)}: every owner with a postcode derives a deterministic
16	 * {@link Id} from its normalized last name and postcode, so owners with the same last name
17	 * and postcode share the same id automatically, regardless of creation order. The id is
18	 * defined once here so the resolver ({@link ResolveHousehold}), the duplicate gate
19	 * ({@link ValidateUniqueIdentity}) and the new owner ({@link BuildOwner}) all agree on it.
20	 */
21	final class Household {
22	
23	    private Household() {
24	    }
25	
26	    /**
27	     * The household identifier published between steps. A dedicated type keeps the variable
28	     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
29	     * the pipeline. {@link #ABSENT} (an empty value) means the new owner has no postcode and
30	     * therefore no household.
31	     */
32	    record Id(String value) {
33	
34	        static final Id ABSENT = new Id("");
35	
36	        boolean isPresent() {
37	            return this.value != null && !this.value.isBlank();
38	        }
39	    }
40	
41	    /**
42	     * Stable identifier for the request's household: the first 12 upper-case hex characters of
43	     * the SHA-256 of {@code normalizedLastName + "|" + postcode}, so every owner with the same
44	     * last name and postcode derives the same value regardless of creation order.
45	     * {@link Id#ABSENT} when the request carries no postcode (no postcode means no household).
46	     */
47	    static Id idFor(OwnerFieldsDto request) {
48	        String postcode = normalizePostcode(request.getPostcode());
49	        if (postcode == null) {
50	            return Id.ABSENT;
51	        }
52	        String seed = normalizeName(request.getLastName()) + "|" + postcode;
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder();
57	            for (int i = 0; i < 6; i++) {
58	                sb.append(String.format("%02X", digest[i]));
59	            }
60	            return new Id(sb.toString());
61	        }
62	        catch (NoSuchAlgorithmException ex) {
63	            throw new IllegalStateException("SHA-256 not available", ex);
64	        }
65	    }
66	
67	    /**
68	     * Whether an owner other than {@code exclude} already carries {@code householdId}. The single
69	     * household-membership lookup, shared by the duplicate gate ({@link ValidateUniqueIdentity},
70	     * which passes {@code exclude = null} because the new owner is not yet persisted) and the
71	     * soft-match rule ({@link PossibleDuplicate}, which excludes the owner itself). Always
72	     * {@code false} for a {@code null}/blank id (an owner with no postcode has no household).
73	     * Scans only {@link ActiveOwners active owners}, so a soft-deleted owner no longer blocks a
74	     * household create.
75	     */
76	    static boolean hasMember(String householdId, Owner exclude, OwnerRepository ownerRepository) {
77	        if (householdId == null || householdId.isBlank()) {
78	            return false;
79	        }
80	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
81	            if (exclude != null && exclude.getId() != null && exclude.getId().equals(existing.getId())) {
82	                continue;
83	            }
84	            if (householdId.equals(existing.getHouseholdId())) {
85	                return true;
86	            }
87	        }
88	        return false;
89	    }
90	
91	    /**
92	     * The number of owners carrying {@code householdId}. The single household-size lookup, reused
93	     * wherever the membership points rule needs a household's member count. {@code 0} for a
94	     * {@code null}/blank id (an owner with no postcode has no household). Scans only
95	     * {@link ActiveOwners active owners}, consistent with {@link #hasMember}, so a soft-deleted
96	     * owner does not count towards a household's size.
97	     */
98	    static int size(String householdId, OwnerRepository ownerRepository) {
99	        if (householdId == null || householdId.isBlank()) {
100	            return 0;
101	        }
102	        int count = 0;
103	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
104	            if (householdId.equals(existing.getHouseholdId())) {
105	                count++;
106	            }
107	        }
108	        return count;
109	    }
110	
111	    /**
112	     * The maximum {@link Owner#getMembershipLevel() membershipLevel} among the members of
113	     * {@code householdId} other than {@code exclude}, or {@link OptionalInt#empty()} when the
114	     * household has no such member (so no cap applies). Each member's household size is resolved
115	     * first — exactly as {@link LoadOwner} does on read — so its level is scored on a fully
116	     * populated household rather than as a lone member. Scans only {@link ActiveOwners active
117	     * owners}, consistent with {@link #size} and {@link #hasMember}, so a soft-deleted owner does
118	     * not raise the ceiling. {@link OptionalInt#empty()} for a {@code null}/blank id.
119	     */
120	    static OptionalInt maxMemberLevel(String householdId, Owner exclude, OwnerRepository ownerRepository) {
121	        if (householdId == null || householdId.isBlank()) {
122	            return OptionalInt.empty();
123	        }
124	        int max = -1;
125	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
126	            if (exclude != null && exclude.getId() != null && exclude.getId().equals(existing.getId())) {
127	                continue;
128	            }
129	            if (householdId.equals(existing.getHouseholdId())) {
130	                existing.setHouseholdSize(Math.max(1, size(householdId, ownerRepository)));
131	                max = Math.max(max, existing.getMembershipLevel());
132	            }
133	        }
134	        return max < 0 ? OptionalInt.empty() : OptionalInt.of(max);
135	    }
136	
137	    /**
138	     * Normalize a last name for the household key: trim, collapse any run of whitespace to a
139	     * single space, and lower-case. Yields {@code ""} for a {@code null} input.
140	     */
141	    private static String normalizeName(String value) {
142	        if (value == null) {
143	            return "";
144	        }
145	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
146	    }
147	
148	    /** Trimmed postcode, or {@code null} when absent/blank (no postcode means no household). */
149	    private static String normalizePostcode(String value) {
150	        if (value == null || value.isBlank()) {
151	            return null;
152	        }
153	        return value.trim();
154	    }
155	}
